insert into kafaa_smr_deltas (id, role_id, tech_id, rank, path_only, dims, changes_en, changes_ar, stays_en, stays_ar, skills, training, concept_role_ids, sources, benchmark_ids, status, listed, version, as_of, sort, updated_by, updated_at) values
('smrd:senior-reactor-operator:tech-bwr', 'senior-reactor-operator', 'tech-bwr', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Crews may supervise several units from one control room, so situational awareness and turnover cover more than one reactor.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. قد تشرف الأطقم على عدة وحدات من غرفة تحكم واحدة، فيمتد الوعي بالموقف وتسليم الوردية إلى أكثر من مفاعل."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Your response to a transient shifts from starting systems to confirming that passive systems are working as designed.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. تنتقل استجابتك للحالات العابرة من تشغيل الأنظمة إلى التأكد من أن الأنظمة الخاملة تعمل كما صُممت."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. New screens, alarm handling and procedures on a different platform; expect simulator time on the new interface.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. شاشات ومعالجة إنذارات وإجراءات جديدة على منصة مختلفة؛ توقّع ساعات على المحاكي للتعرف على الواجهة الجديدة."},{"dim":"factory_fab","change":"adapts","text_en":"More of the plant arrives as factory-built modules, so quality evidence moves upstream to the factory. Fewer site-built systems to walk down during commissioning and more vendor documentation to learn before you operate.","text_ar":"يصل جزء أكبر من المحطة على شكل وحدات مصنّعة في المصنع، فتنتقل أدلة الجودة إلى المصنع. أنظمة مبنية في الموقع أقل للتفقد أثناء التشغيل التجريبي، ووثائق موردين أكثر لتتعلمها قبل التشغيل."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance windows and refuelling follow a different design basis and outage rhythm. Equipment outages and their rhythm change, so rounds and tagging follow a new pattern.","text_ar":"تتبع نوافذ الصيانة والتزويد بالوقود أساس تصميم وإيقاع إيقاف مختلفين. يتغير خروج المعدات من الخدمة وإيقاعه، فتتبع الجولات وعمليات العزل نمطاً جديداً."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. Plant systems behave differently, so your mental model of the plant has to be rebuilt system by system.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. تتصرف أنظمة المحطة بشكل مختلف، فيجب إعادة بناء تصورك الذهني للمحطة نظاماً بعد نظام."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Conservative decision-making, procedure use, shift turnover and the questioning attitude you practise on Barakah''s APR-1400 units carry over unchanged.', 'يبقى اتخاذ القرار المحافظ واستخدام الإجراءات وتسليم الوردية والتساؤل الذي تمارسه في وحدات APR-1400 في براكة كما هو.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-bwr-operator']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 1, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:senior-reactor-operator:tech-micro', 'senior-reactor-operator', 'tech-micro', 2, false, '[{"dim":"multi_module","change":"new","text_en":"Many small transportable units rather than one plant. Crews may supervise several units from one control room, so situational awareness and turnover cover more than one reactor.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. قد تشرف الأطقم على عدة وحدات من غرفة تحكم واحدة، فيمتد الوعي بالموقف وتسليم الوردية إلى أكثر من مفاعل."},{"dim":"passive_safety","change":"new","text_en":"Microreactor concepts are designed to cool themselves passively for long periods. Your response to a transient shifts from starting systems to confirming that passive systems are working as designed.","text_ar":"صُممت مفاهيم المفاعلات المتناهية الصغر لتبريد نفسها بطريقة خاملة لفترات طويلة. تنتقل استجابتك للحالات العابرة من تشغيل الأنظمة إلى التأكد من أن الأنظمة الخاملة تعمل كما صُممت."},{"dim":"digital_ic","change":"new","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. New screens, alarm handling and procedures on a different platform; expect simulator time on the new interface.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. شاشات ومعالجة إنذارات وإجراءات جديدة على منصة مختلفة؛ توقّع ساعات على المحاكي للتعرف على الواجهة الجديدة."},{"dim":"factory_fab","change":"adapts","text_en":"Units are built in a factory and transported as complete units. Fewer site-built systems to walk down during commissioning and more vendor documentation to learn before you operate.","text_ar":"تُبنى الوحدات في المصنع وتُنقل وحدات كاملة. أنظمة مبنية في الموقع أقل للتفقد أثناء التشغيل التجريبي، ووثائق موردين أكثر لتتعلمها قبل التشغيل."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance shifts towards remote monitoring and returning units to the factory. Equipment outages and their rhythm change, so rounds and tagging follow a new pattern.","text_ar":"تنتقل الصيانة نحو المراقبة عن بعد وإعادة الوحدات إلى المصنع. يتغير خروج المعدات من الخدمة وإيقاعه، فتتبع الجولات وعمليات العزل نمطاً جديداً."},{"dim":"systems","change":"adapts","text_en":"Compact designs with their own coolant and fuel choices. Plant systems behave differently, so your mental model of the plant has to be rebuilt system by system.","text_ar":"تصاميم مدمجة لها خياراتها الخاصة من المبرد والوقود. تتصرف أنظمة المحطة بشكل مختلف، فيجب إعادة بناء تصورك الذهني للمحطة نظاماً بعد نظام."}]'::jsonb, 'Microreactors: the biggest shifts for this role are multi-module operation, passive safety and digital I&C; factory fabrication, the maintenance regime and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والسلامة الخاملة، والأجهزة والتحكم الرقمية، بينما يتكيف كل من التصنيع في المصنع، ونظام الصيانة، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Conservative decision-making, procedure use, shift turnover and the questioning attitude you practise on Barakah''s APR-1400 units carry over unchanged.', 'يبقى اتخاذ القرار المحافظ واستخدام الإجراءات وتسليم الوردية والتساؤل الذي تمارسه في وحدات APR-1400 في براكة كما هو.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-adv-micro","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-adv-micro-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"},{"id":"iaea-ai-bulletin","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence (2025)","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 2, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:senior-reactor-operator:tech-htgr', 'senior-reactor-operator', 'tech-htgr', 3, false, '[{"dim":"multi_module","change":"new","text_en":"Several smaller reactor modules may share one plant and one control room. Crews may supervise several units from one control room, so situational awareness and turnover cover more than one reactor.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. قد تشرف الأطقم على عدة وحدات من غرفة تحكم واحدة، فيمتد الوعي بالموقف وتسليم الوردية إلى أكثر من مفاعل."},{"dim":"passive_safety","change":"new","text_en":"Gas-cooled designs aim to remove decay heat passively, relying on fuel and materials that tolerate high temperatures. Your response to a transient shifts from starting systems to confirming that passive systems are working as designed.","text_ar":"تسعى التصاميم المبرّدة بالغاز إلى إزالة حرارة الاضمحلال بطريقة خاملة، معتمدة على وقود ومواد تتحمل درجات حرارة عالية. تنتقل استجابتك للحالات العابرة من تشغيل الأنظمة إلى التأكد من أن الأنظمة الخاملة تعمل كما صُممت."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. New screens, alarm handling and procedures on a different platform; expect simulator time on the new interface.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. شاشات ومعالجة إنذارات وإجراءات جديدة على منصة مختلفة؛ توقّع ساعات على المحاكي للتعرف على الواجهة الجديدة."},{"dim":"factory_fab","change":"adapts","text_en":"Reactor modules and major components are planned to be factory-built. Fewer site-built systems to walk down during commissioning and more vendor documentation to learn before you operate.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. أنظمة مبنية في الموقع أقل للتفقد أثناء التشغيل التجريبي، ووثائق موردين أكثر لتتعلمها قبل التشغيل."},{"dim":"maintenance","change":"adapts","text_en":"Gas coolant and a different fuel form change inspection and maintenance tasks. Equipment outages and their rhythm change, so rounds and tagging follow a new pattern.","text_ar":"يغيّر التبريد بالغاز وشكل الوقود المختلف مهام الفحص والصيانة. يتغير خروج المعدات من الخدمة وإيقاعه، فتتبع الجولات وعمليات العزل نمطاً جديداً."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. Plant systems behave differently, so your mental model of the plant has to be rebuilt system by system.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. تتصرف أنظمة المحطة بشكل مختلف، فيجب إعادة بناء تصورك الذهني للمحطة نظاماً بعد نظام."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are multi-module operation, passive safety and plant systems, coolant and fuel; digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والسلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Conservative decision-making, procedure use, shift turnover and the questioning attitude you practise on Barakah''s APR-1400 units carry over unchanged.', 'يبقى اتخاذ القرار المحافظ واستخدام الإجراءات وتسليم الوردية والتساؤل الذي تمارسه في وحدات APR-1400 في براكة كما هو.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 3, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:shift-supervisor:tech-bwr', 'shift-supervisor', 'tech-bwr', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Crews may supervise several units from one control room, so situational awareness and turnover cover more than one reactor.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. قد تشرف الأطقم على عدة وحدات من غرفة تحكم واحدة، فيمتد الوعي بالموقف وتسليم الوردية إلى أكثر من مفاعل."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Your response to a transient shifts from starting systems to confirming that passive systems are working as designed.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. تنتقل استجابتك للحالات العابرة من تشغيل الأنظمة إلى التأكد من أن الأنظمة الخاملة تعمل كما صُممت."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. New screens, alarm handling and procedures on a different platform; expect simulator time on the new interface.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. شاشات ومعالجة إنذارات وإجراءات جديدة على منصة مختلفة؛ توقّع ساعات على المحاكي للتعرف على الواجهة الجديدة."},{"dim":"factory_fab","change":"adapts","text_en":"More of the plant arrives as factory-built modules, so quality evidence moves upstream to the factory. Fewer site-built systems to walk down during commissioning and more vendor documentation to learn before you operate.","text_ar":"يصل جزء أكبر من المحطة على شكل وحدات مصنّعة في المصنع، فتنتقل أدلة الجودة إلى المصنع. أنظمة مبنية في الموقع أقل للتفقد أثناء التشغيل التجريبي، ووثائق موردين أكثر لتتعلمها قبل التشغيل."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance windows and refuelling follow a different design basis and outage rhythm. Equipment outages and their rhythm change, so rounds and tagging follow a new pattern.","text_ar":"تتبع نوافذ الصيانة والتزويد بالوقود أساس تصميم وإيقاع إيقاف مختلفين. يتغير خروج المعدات من الخدمة وإيقاعه، فتتبع الجولات وعمليات العزل نمطاً جديداً."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. Plant systems behave differently, so your mental model of the plant has to be rebuilt system by system.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. تتصرف أنظمة المحطة بشكل مختلف، فيجب إعادة بناء تصورك الذهني للمحطة نظاماً بعد نظام."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Conservative decision-making, procedure use, shift turnover and the questioning attitude you practise on Barakah''s APR-1400 units carry over unchanged.', 'يبقى اتخاذ القرار المحافظ واستخدام الإجراءات وتسليم الوردية والتساؤل الذي تمارسه في وحدات APR-1400 في براكة كما هو.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 4, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:shift-supervisor:tech-micro', 'shift-supervisor', 'tech-micro', 2, false, '[{"dim":"multi_module","change":"new","text_en":"Many small transportable units rather than one plant. Crews may supervise several units from one control room, so situational awareness and turnover cover more than one reactor.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. قد تشرف الأطقم على عدة وحدات من غرفة تحكم واحدة، فيمتد الوعي بالموقف وتسليم الوردية إلى أكثر من مفاعل."},{"dim":"passive_safety","change":"new","text_en":"Microreactor concepts are designed to cool themselves passively for long periods. Your response to a transient shifts from starting systems to confirming that passive systems are working as designed.","text_ar":"صُممت مفاهيم المفاعلات المتناهية الصغر لتبريد نفسها بطريقة خاملة لفترات طويلة. تنتقل استجابتك للحالات العابرة من تشغيل الأنظمة إلى التأكد من أن الأنظمة الخاملة تعمل كما صُممت."},{"dim":"digital_ic","change":"new","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. New screens, alarm handling and procedures on a different platform; expect simulator time on the new interface.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. شاشات ومعالجة إنذارات وإجراءات جديدة على منصة مختلفة؛ توقّع ساعات على المحاكي للتعرف على الواجهة الجديدة."},{"dim":"factory_fab","change":"adapts","text_en":"Units are built in a factory and transported as complete units. Fewer site-built systems to walk down during commissioning and more vendor documentation to learn before you operate.","text_ar":"تُبنى الوحدات في المصنع وتُنقل وحدات كاملة. أنظمة مبنية في الموقع أقل للتفقد أثناء التشغيل التجريبي، ووثائق موردين أكثر لتتعلمها قبل التشغيل."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance shifts towards remote monitoring and returning units to the factory. Equipment outages and their rhythm change, so rounds and tagging follow a new pattern.","text_ar":"تنتقل الصيانة نحو المراقبة عن بعد وإعادة الوحدات إلى المصنع. يتغير خروج المعدات من الخدمة وإيقاعه، فتتبع الجولات وعمليات العزل نمطاً جديداً."},{"dim":"systems","change":"adapts","text_en":"Compact designs with their own coolant and fuel choices. Plant systems behave differently, so your mental model of the plant has to be rebuilt system by system.","text_ar":"تصاميم مدمجة لها خياراتها الخاصة من المبرد والوقود. تتصرف أنظمة المحطة بشكل مختلف، فيجب إعادة بناء تصورك الذهني للمحطة نظاماً بعد نظام."}]'::jsonb, 'Microreactors: the biggest shifts for this role are multi-module operation, passive safety and digital I&C; factory fabrication, the maintenance regime and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والسلامة الخاملة، والأجهزة والتحكم الرقمية، بينما يتكيف كل من التصنيع في المصنع، ونظام الصيانة، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Conservative decision-making, procedure use, shift turnover and the questioning attitude you practise on Barakah''s APR-1400 units carry over unchanged.', 'يبقى اتخاذ القرار المحافظ واستخدام الإجراءات وتسليم الوردية والتساؤل الذي تمارسه في وحدات APR-1400 في براكة كما هو.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-adv-micro","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-adv-micro-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"},{"id":"iaea-ai-bulletin","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence (2025)","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 5, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:shift-supervisor:tech-htgr', 'shift-supervisor', 'tech-htgr', 3, false, '[{"dim":"multi_module","change":"new","text_en":"Several smaller reactor modules may share one plant and one control room. Crews may supervise several units from one control room, so situational awareness and turnover cover more than one reactor.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. قد تشرف الأطقم على عدة وحدات من غرفة تحكم واحدة، فيمتد الوعي بالموقف وتسليم الوردية إلى أكثر من مفاعل."},{"dim":"passive_safety","change":"new","text_en":"Gas-cooled designs aim to remove decay heat passively, relying on fuel and materials that tolerate high temperatures. Your response to a transient shifts from starting systems to confirming that passive systems are working as designed.","text_ar":"تسعى التصاميم المبرّدة بالغاز إلى إزالة حرارة الاضمحلال بطريقة خاملة، معتمدة على وقود ومواد تتحمل درجات حرارة عالية. تنتقل استجابتك للحالات العابرة من تشغيل الأنظمة إلى التأكد من أن الأنظمة الخاملة تعمل كما صُممت."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. New screens, alarm handling and procedures on a different platform; expect simulator time on the new interface.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. شاشات ومعالجة إنذارات وإجراءات جديدة على منصة مختلفة؛ توقّع ساعات على المحاكي للتعرف على الواجهة الجديدة."},{"dim":"factory_fab","change":"adapts","text_en":"Reactor modules and major components are planned to be factory-built. Fewer site-built systems to walk down during commissioning and more vendor documentation to learn before you operate.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. أنظمة مبنية في الموقع أقل للتفقد أثناء التشغيل التجريبي، ووثائق موردين أكثر لتتعلمها قبل التشغيل."},{"dim":"maintenance","change":"adapts","text_en":"Gas coolant and a different fuel form change inspection and maintenance tasks. Equipment outages and their rhythm change, so rounds and tagging follow a new pattern.","text_ar":"يغيّر التبريد بالغاز وشكل الوقود المختلف مهام الفحص والصيانة. يتغير خروج المعدات من الخدمة وإيقاعه، فتتبع الجولات وعمليات العزل نمطاً جديداً."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. Plant systems behave differently, so your mental model of the plant has to be rebuilt system by system.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. تتصرف أنظمة المحطة بشكل مختلف، فيجب إعادة بناء تصورك الذهني للمحطة نظاماً بعد نظام."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are multi-module operation, passive safety and plant systems, coolant and fuel; digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والسلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Conservative decision-making, procedure use, shift turnover and the questioning attitude you practise on Barakah''s APR-1400 units carry over unchanged.', 'يبقى اتخاذ القرار المحافظ واستخدام الإجراءات وتسليم الوردية والتساؤل الذي تمارسه في وحدات APR-1400 في براكة كما هو.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 6, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:reactor-operator:tech-bwr', 'reactor-operator', 'tech-bwr', 1, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Crews may supervise several units from one control room, so situational awareness and turnover cover more than one reactor.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. قد تشرف الأطقم على عدة وحدات من غرفة تحكم واحدة، فيمتد الوعي بالموقف وتسليم الوردية إلى أكثر من مفاعل."},{"dim":"passive_safety","change":"new","text_en":"Small reactor designs put more weight on passive cooling that works for a period without AC power or operator action. Your response to a transient shifts from starting systems to confirming that passive systems are working as designed.","text_ar":"تعطي تصاميم المفاعلات الصغيرة وزناً أكبر للتبريد الخامل الذي يعمل لفترة دون كهرباء متناوبة أو تدخل من المشغلين. تنتقل استجابتك للحالات العابرة من تشغيل الأنظمة إلى التأكد من أن الأنظمة الخاملة تعمل كما صُممت."},{"dim":"digital_ic","change":"adapts","text_en":"A different digital control platform and alarm philosophy from the APR-1400 digital I&C you know. New screens, alarm handling and procedures on a different platform; expect simulator time on the new interface.","text_ar":"منصة تحكم رقمية وفلسفة إنذارات تختلفان عن الأجهزة والتحكم الرقمية في APR-1400 التي تعرفها. شاشات ومعالجة إنذارات وإجراءات جديدة على منصة مختلفة؛ توقّع ساعات على المحاكي للتعرف على الواجهة الجديدة."},{"dim":"factory_fab","change":"adapts","text_en":"More of the plant arrives as factory-built modules, so quality evidence moves upstream to the factory. Fewer site-built systems to walk down during commissioning and more vendor documentation to learn before you operate.","text_ar":"يصل جزء أكبر من المحطة على شكل وحدات مصنّعة في المصنع، فتنتقل أدلة الجودة إلى المصنع. أنظمة مبنية في الموقع أقل للتفقد أثناء التشغيل التجريبي، ووثائق موردين أكثر لتتعلمها قبل التشغيل."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance windows and refuelling follow a different design basis and outage rhythm. Equipment outages and their rhythm change, so rounds and tagging follow a new pattern.","text_ar":"تتبع نوافذ الصيانة والتزويد بالوقود أساس تصميم وإيقاع إيقاف مختلفين. يتغير خروج المعدات من الخدمة وإيقاعه، فتتبع الجولات وعمليات العزل نمطاً جديداً."},{"dim":"systems","change":"new","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. Plant systems behave differently, so your mental model of the plant has to be rebuilt system by system.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. تتصرف أنظمة المحطة بشكل مختلف، فيجب إعادة بناء تصورك الذهني للمحطة نظاماً بعد نظام."}]'::jsonb, 'Small boiling water reactor: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation, digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Conservative decision-making, procedure use, shift turnover and the questioning attitude you practise on Barakah''s APR-1400 units carry over unchanged.', 'يبقى اتخاذ القرار المحافظ واستخدام الإجراءات وتسليم الوردية والتساؤل الذي تمارسه في وحدات APR-1400 في براكة كما هو.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, array['fr-bwr-operator']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 7, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:reactor-operator:tech-micro', 'reactor-operator', 'tech-micro', 2, false, '[{"dim":"multi_module","change":"new","text_en":"Many small transportable units rather than one plant. Crews may supervise several units from one control room, so situational awareness and turnover cover more than one reactor.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. قد تشرف الأطقم على عدة وحدات من غرفة تحكم واحدة، فيمتد الوعي بالموقف وتسليم الوردية إلى أكثر من مفاعل."},{"dim":"passive_safety","change":"new","text_en":"Microreactor concepts are designed to cool themselves passively for long periods. Your response to a transient shifts from starting systems to confirming that passive systems are working as designed.","text_ar":"صُممت مفاهيم المفاعلات المتناهية الصغر لتبريد نفسها بطريقة خاملة لفترات طويلة. تنتقل استجابتك للحالات العابرة من تشغيل الأنظمة إلى التأكد من أن الأنظمة الخاملة تعمل كما صُممت."},{"dim":"digital_ic","change":"new","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. New screens, alarm handling and procedures on a different platform; expect simulator time on the new interface.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. شاشات ومعالجة إنذارات وإجراءات جديدة على منصة مختلفة؛ توقّع ساعات على المحاكي للتعرف على الواجهة الجديدة."},{"dim":"factory_fab","change":"adapts","text_en":"Units are built in a factory and transported as complete units. Fewer site-built systems to walk down during commissioning and more vendor documentation to learn before you operate.","text_ar":"تُبنى الوحدات في المصنع وتُنقل وحدات كاملة. أنظمة مبنية في الموقع أقل للتفقد أثناء التشغيل التجريبي، ووثائق موردين أكثر لتتعلمها قبل التشغيل."},{"dim":"maintenance","change":"adapts","text_en":"Maintenance shifts towards remote monitoring and returning units to the factory. Equipment outages and their rhythm change, so rounds and tagging follow a new pattern.","text_ar":"تنتقل الصيانة نحو المراقبة عن بعد وإعادة الوحدات إلى المصنع. يتغير خروج المعدات من الخدمة وإيقاعه، فتتبع الجولات وعمليات العزل نمطاً جديداً."},{"dim":"systems","change":"adapts","text_en":"Compact designs with their own coolant and fuel choices. Plant systems behave differently, so your mental model of the plant has to be rebuilt system by system.","text_ar":"تصاميم مدمجة لها خياراتها الخاصة من المبرد والوقود. تتصرف أنظمة المحطة بشكل مختلف، فيجب إعادة بناء تصورك الذهني للمحطة نظاماً بعد نظام."}]'::jsonb, 'Microreactors: the biggest shifts for this role are multi-module operation, passive safety and digital I&C; factory fabrication, the maintenance regime and plant systems, coolant and fuel adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والسلامة الخاملة، والأجهزة والتحكم الرقمية، بينما يتكيف كل من التصنيع في المصنع، ونظام الصيانة، وأنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Conservative decision-making, procedure use, shift turnover and the questioning attitude you practise on Barakah''s APR-1400 units carry over unchanged.', 'يبقى اتخاذ القرار المحافظ واستخدام الإجراءات وتسليم الوردية والتساؤل الذي تمارسه في وحدات APR-1400 في براكة كما هو.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":2},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-adv-micro","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-adv-micro-l1"}]'::jsonb, array['fr-remote-ops']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"},{"id":"iaea-ai-bulletin","label":"IAEA Bulletin · Enhancing nuclear power production with artificial intelligence (2025)","url":"https://iaea.org/bulletin/enhancing-nuclear-power-production-with-artificial-intelligence","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 8, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:reactor-operator:tech-htgr', 'reactor-operator', 'tech-htgr', 3, false, '[{"dim":"multi_module","change":"new","text_en":"Several smaller reactor modules may share one plant and one control room. Crews may supervise several units from one control room, so situational awareness and turnover cover more than one reactor.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. قد تشرف الأطقم على عدة وحدات من غرفة تحكم واحدة، فيمتد الوعي بالموقف وتسليم الوردية إلى أكثر من مفاعل."},{"dim":"passive_safety","change":"new","text_en":"Gas-cooled designs aim to remove decay heat passively, relying on fuel and materials that tolerate high temperatures. Your response to a transient shifts from starting systems to confirming that passive systems are working as designed.","text_ar":"تسعى التصاميم المبرّدة بالغاز إلى إزالة حرارة الاضمحلال بطريقة خاملة، معتمدة على وقود ومواد تتحمل درجات حرارة عالية. تنتقل استجابتك للحالات العابرة من تشغيل الأنظمة إلى التأكد من أن الأنظمة الخاملة تعمل كما صُممت."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. New screens, alarm handling and procedures on a different platform; expect simulator time on the new interface.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. شاشات ومعالجة إنذارات وإجراءات جديدة على منصة مختلفة؛ توقّع ساعات على المحاكي للتعرف على الواجهة الجديدة."},{"dim":"factory_fab","change":"adapts","text_en":"Reactor modules and major components are planned to be factory-built. Fewer site-built systems to walk down during commissioning and more vendor documentation to learn before you operate.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. أنظمة مبنية في الموقع أقل للتفقد أثناء التشغيل التجريبي، ووثائق موردين أكثر لتتعلمها قبل التشغيل."},{"dim":"maintenance","change":"adapts","text_en":"Gas coolant and a different fuel form change inspection and maintenance tasks. Equipment outages and their rhythm change, so rounds and tagging follow a new pattern.","text_ar":"يغيّر التبريد بالغاز وشكل الوقود المختلف مهام الفحص والصيانة. يتغير خروج المعدات من الخدمة وإيقاعه، فتتبع الجولات وعمليات العزل نمطاً جديداً."},{"dim":"systems","change":"new","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. Plant systems behave differently, so your mental model of the plant has to be rebuilt system by system.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. تتصرف أنظمة المحطة بشكل مختلف، فيجب إعادة بناء تصورك الذهني للمحطة نظاماً بعد نظام."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are multi-module operation, passive safety and plant systems, coolant and fuel; digital I&C, factory fabrication and the maintenance regime adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في التشغيل متعدد الوحدات، والسلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من الأجهزة والتحكم الرقمية، والتصنيع في المصنع، ونظام الصيانة. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Conservative decision-making, procedure use, shift turnover and the questioning attitude you practise on Barakah''s APR-1400 units carry over unchanged.', 'يبقى اتخاذ القرار المحافظ واستخدام الإجراءات وتسليم الوردية والتساؤل الذي تمارسه في وحدات APR-1400 في براكة كما هو.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":2},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"osu-e2-center","label":"Oregon State University · NuScale Energy Exploration (E2) Center","url":"https://engineering.oregonstate.edu/facilities/energy-exploration-e2-center","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 9, 'p-training-mgr', '2026-10-11T08:00:00Z')
